/**
 * Busca a query no provedor (todas as páginas) e confere que a edição existe nela; o maior
 * episódio da edição vira o último encontrado. Um anime só tem um rastreio. Anime vinculado
 * a uma pasta de outro storage provider que não o da biblioteca responde `409`, como no
 * download.
 * @summary Começa a rastrear um anime numa edição de um provedor de torrent
 */
export const trackAnime = async (
  trackedAnimeRequestBodyBody: TrackedAnimeRequestBodyBody,
  options?: Parameters<typeof apiFetch>[1],
): Promise<TrackedAnimeCreatedResponse> => {
  const getHeaders = (
    h?: NonNullable<RequestInit['headers']>,
  ): Record<string, string | readonly string[]> => {
    if (!h) return {}
    if (h instanceof Headers) return Object.fromEntries(h.entries())
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(
          h as Iterable<Iterable<string>>,
          (entry) => Array.from(entry) as [string, string],
        ),
      )
    }
    const headers: Record<string, string | readonly string[]> = {}
    for (const [name, value] of Object.entries<
      string | readonly string[] | undefined
    >(h)) {
      if (value !== undefined) headers[name] = value
    }
    return headers
  }
  return apiFetch<TrackedAnimeCreatedResponse>(getTrackAnimeUrl(), {
    ...options,
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      ...getHeaders(options?.headers),
    },
    body: JSON.stringify(trackedAnimeRequestBodyBody),
  })
}

